\label{thm:Main1}
	Let $G$ be a connected graph. There exists a multiplicity $\mu$ such that the connected subgraph multiarrangement $({\mathscr A}_G,\mu)$ is free if and only if $G$ is $G_1$, $G_2$, a path-graph, a cycle-graph, an almost-path-graph, or a path-with-triangle-graph (see Definition \ref{definition: cuntz kühne graph families}
	and Figure \ref{fig:G1_8}).

\label{thm:Main3}
	Let $(\mathscr{D},\mu)$ be the multiarrangement $$Q(\mathscr{D},\mu)=x_1^ax_2^bx_3^c(x_1+x_2)^d(x_1+x_3)^e(x_2+x_3)^f$$ with $a,b,c,d,e,f \geq 1$. Then
	$(\mathscr{D},\mu)$ is free if and only if  $\mu=(2k,2k,2k,1,1,1)$ for some $k\in\mathbb{N}_{\geq 1}$ where the order of the hyperplanes is as above.

\label{thm:Main4}
	Let $({\mathscr A}_{C_3},\mu)$ be the multiarrangement $$Q({\mathscr A}_{C_3},\mu)=x_1^ax_2^bx_3^c(x_1+x_2)^d(x_1+x_3)^e(x_2+x_3)^f(x_1+x_2+x_3)^g$$ with multiplicity $\mu=(a,b,c,d,e,f,g), (d\geq e\geq f)$. Suppose that either 
	\begin{enumerate}
		\item[(i)] $\mu=(k,k,k,r,1,1,k)$, where $1\leq k \leq 3$ and $r\geq 1$, or
		\item[(ii)] $\mu=(k,k,k,r,1,1,k)$, where $k>3$ and $r\geq 2k-5$.
	\end{enumerate}
	Then $({\mathscr A}_{C_3},\mu)$ is free. Moreover, if $r\geq 2k$, then $({\mathscr A}_{C_3},\mu)$ is  inductively free with exponents $(r,2k+1,2k+1)$.
    For $\mu = (3,3,3,1,1,1,3)$, $({\mathscr A}_{C_3},\mu)$ is not inductively free.

\label{Theorem:localFreeness}
	Suppose ${\mathscr A}$ is an arrangement in ${\mathbb K}^\ell$ with $\ell > 3$.
	Then ${\mathscr A}$ is free with exponents $(1 = e_1,e_2, \dots,e_\ell)$ if and only if it is locally free along $H$ for some $H\in {\mathscr A}$ and $({\mathscr A}^H,\kappa)$ is free with exponents $(e_2,\dots,e_\ell)$.

\label{Cor: LocalFreeChaPolFactor}
	Suppose ${\mathscr A}$ is an arrangement in ${\mathbb K}^\ell$ with $\ell > 3$. 
	Let ${\mathscr A}$ be locally free along $H\in {\mathscr A}$. If ${\mathscr A}_X$ fails to be free for some $X\in L({\mathscr A})$ with $X\not\subset H$, then $({\mathscr A}^H,\kappa)$ is not free.

\label{ATWEulerProp}
	Let $({\mathscr A},\mu)$ be a multiarrangement. Let $X\in{\mathscr A}^{H_0}$, $m_0=\mu(H_0)$, $k=\vert {\mathscr A}_X\vert$, and $m_1=\max\{\mu(H)\mid H\in {\mathscr A}_X\backslash\{H_0\}\}$.
	\begin{itemize}
		\item[(i)] If $k=2$, then $\mu^*(X)=m_1$.
		\item[(ii)] If $\vert \mu_X\vert\leq 2k-1$ and $m_0>1$, then $\mu^*(X)=k-1$.
		\item[(iii)] If $\mu_X\equiv 2$, then $\mu^*(X)=k$.
	\end{itemize}

\label{thm:add-del}
	Suppose that $({\mathscr A}, \mu) \ne \Phi_\ell$.
	Fix $H_0$ in ${\mathscr A}$ and 
	let  $({\mathscr A}, \mu), ({\mathscr A}', \mu')$ and  $({\mathscr A}'', \mu^*)$ be the triple with respect to $H_0$. 
	Then any  two of the following statements imply the third:
	\begin{itemize}
		\item[(i)] $({\mathscr A}, \mu)$ is free with $\exp ({\mathscr A}, \mu) = (e_1, \ldots , e_{\ell -1}, b_\ell)$;
		\item[(ii)] $({\mathscr A}', \mu')$ is free with $\exp ({\mathscr A}', \mu') = (e_1, \ldots , e_{\ell -1}, b_\ell-1)$;
		\item[(iii)] $({\mathscr A}'', \mu^*)$ is free with $\exp ({\mathscr A}'', \mu^*) = (e_1, \ldots , e_{\ell -1})$.
	\end{itemize}

\label{rem:AddDelThm_multi_simple}
	If we restrict to simple multiplicities, Theorem \ref{thm:add-del} 
	recovers Terao's original Addition-Deletion Theorem 

 from \cite{terao:freeI}. As in the simple case if $({\mathscr A}, \mu)$ and $({\mathscr A}',\mu')$ are free, then all three statements of Theorem \ref{thm:add-del} hold (see \cite[Thm.~0.4]{abeteraowakefield:euler}).

\label{def:indfree}
	The class ${\mathcal {IFM}}$ of \emph{inductively free} multiarrangements 
	is the smallest class of multiarrangements subject to
	\begin{itemize}
		\item[(i)] $\Phi_\ell \in {\mathcal {IFM}}$ for each $\ell \ge 0$;
		\item[(ii)] for a multiarrangement $({\mathscr A}, \mu)$, if there exists a hyperplane $H_0 \in {\mathscr A}$ such that both
		$({\mathscr A}', \mu')$ and $({\mathscr A}'', \mu^*)$ belong to ${\mathcal {IFM}}$, and $\exp ({\mathscr A}'', \mu^*) \subseteq \exp ({\mathscr A}', \mu')$, 
		then $({\mathscr A}, \mu)$ also belongs to ${\mathcal {IFM}}$.
	\end{itemize}

\label{def:recfree-mult}
	The class ${\mathcal {RFM}}$ of \emph{recursively free} multiarrangements 
	is the smallest class of multiarrangements subject to
	\begin{itemize}
		\item[(i)] $\Phi_\ell \in {\mathcal {RFM}}$ for each $\ell \ge 0$;
		\item[(ii)] for a multiarrangement $({\mathscr A}, \mu)$, if there exists a hyperplane $H_0 \in {\mathscr A}$ such that both
		$({\mathscr A}', \mu')$ and $({\mathscr A}'', \mu^*)$ belong to ${\mathcal {RFM}}$, and $\exp ({\mathscr A}'', \mu^*) \subseteq \exp ({\mathscr A}', \mu')$, 
		then $({\mathscr A}, \mu)$ also belongs to ${\mathcal {RFM}}$.
		\item[(iii)] for a multiarrangement $({\mathscr A}, \mu)$, if there exists a hyperplane $H_0 \in {\mathscr A}$ such that both
		$({\mathscr A}, \mu)$ and $({\mathscr A}'', \mu^*)$ belong to ${\mathcal {RFM}}$, and $\exp ({\mathscr A}'', \mu^*) \subseteq \exp ({\mathscr A}, \mu)$, 
		then $({\mathscr A}', \mu')$ also belongs to ${\mathcal {RFM}}$.
	\end{itemize}

\label{WakaTheo}
	Let ${\mathscr A}=\{H_1,H_2,H_3\}$ be a $2$-arrangement of three lines, $\mu$ a multiplicity on ${\mathscr A}$ with $\mu(H_i)=k_i,(i=1,2,3)$ and $\exp({\mathscr A},\mu)=(e_1,e_2)$. Assume that $k_3\geq\max\{k_1,k_2\}$ and let $k=k_1+k_2+k_3$.
	\begin{itemize}
		\item[(i)] If $k_3< k_1+k_2-1$, then  
		\begin{equation*}
			\vert e_1-e_2\vert =
			\begin{cases}
				0 & \text{if $k$ is even,}\\
				1 & \text{if $k$ is odd.}\\
			\end{cases}       
		\end{equation*}
		\item[(ii)] If $k_3 \geq k_1+k_2-1$, then $\exp({\mathscr A},\mu)=(k_1+k_2,k_3)$.
	\end{itemize}

