\label{lemma: connected subgraph arrangements are locallyA2}
	For pairwise distinct nonempty subsets $A_1, A_2, A_3\subseteq  [n]$ and $n\geq1$ the following two conditions are equivalent:
	\begin{itemize}
		\item[(i)] $\operatorname{rank}(H_{A_1}\cap H_{A_2}\cap H_{A_3})=2$ and
		\item[(ii)] $A_{i_1}\dot{\cup}A_{i_2} = A_{i_3}$ for some choice of pairwise distinct indices $1 \leq i_1, i_2, i_3 \leq 3$ where $\dot{\cup}$
		denotes a disjoint set union.
	\end{itemize}

\label{def:localag}
	Let $G=(N,E)$ be a graph and $e=\{i,j\}\in E$ an edge. We denote by $G/e$ the graph with contracted edge $e$, i.e. the graph in which the vertices $i,j$ are identified to one vertex $k$, each edge to $i$ or $j$ becomes an edge to $k$, and multiple edges and loops are removed.
	For $S \subseteq N$ the \emph{induced subgraph} of $G$ on $S$ we denote by $G[S] = (S,E\cap\binom{S}{2})$.

\label{lemma:ind_subgraph contract localization}

	Let $G=(N,E)$ be a graph. Then
	\begin{itemize}
		\item[(i)] for $S \subseteq N$ we have ${\mathscr A}_{G[S]} = ({\mathscr A}_G)_X$ for some $X \in L({\mathscr A}_G)$, and
		\item[(ii)] for $e \in E$, ${\mathscr A}_{G/{e}} = ({\mathscr A}_G)_X$ for some $X \in L({\mathscr A}_G)$.
	\end{itemize}
	In particular, if $P$ is a local arrangement property satisfied by ${\mathscr A}_G$, then both ${\mathscr A}_{G[S]}$ and ${\mathscr A}_{G/e}$ satisfy $P$ as well.

\label{definition: Yoshinga extension}
	Let $({\mathscr A},\mu)$ be a free multiarrangement in $\mathbb{C}^\ell$. 
	\begin{itemize}
		\item[(i)] $({\mathscr A},\mu)$ is \emph{extendable} if it can be obtained as a Ziegler restriction of a free arrangement in $\mathbb{C}^{\ell+1}$.
		\item[(ii)] Define an extension in $\mathbb{C}^{\ell+1}$                                     
		with $(x_1,x_2,\dots,x_\ell,x_{\ell+1})$ as a coordinate system by
		\[{\mathscr E}({\mathscr A},\mu)=\{\ker(x_{\ell+1})\}\cup\left\{\ker(\alpha_H-kx_{\ell+1})\ \middle| \  k\in\mathbb{Z},-\frac{\mu(H)-1}{2}\leq k\leq \frac{\mu(H)}{2}, H \in {\mathscr A}\right\}.\]
		Note that $({\mathscr E}({\mathscr A},\mu)^{\ker(x_{\ell+1})},\kappa)=({\mathscr A},\mu)$.
	\end{itemize}

\label{theorem: Yoshinaga extendable theorem}
	Let ${\mathscr A}$ be a locally $A_2$ arrangement with a positive system in $V=\mathbb{C}^\ell$. We fix a positive system $\Phi^+=\{\alpha_H\mid H\in{\mathscr A}\}\subset V^*$ of defining equations. Let $\mu:{\mathscr A}\to \mathbb{Z}_{\geq 0}$ be a multiplicity. Assume the following condition:
\begin{equation}
\label{eq:star} 
\parbox[c]{14cm}{\text{Let ${\mathscr A}_X=\{H_i,H_j,H_k\}$ be a codimension two localization with $\alpha_i=\alpha_j+\alpha_k$.} 
\text{If $\mu(H_i)$ is odd, then at least one of $\mu(H_j)$ or $\mu(H_k)$ is odd.}
}
\end{equation}

	Then $({\mathscr A},\mu)$ is free, if and only if it is extendable. Indeed, ${\mathscr E}({\mathscr A},\mu)$ is a free arrangement.

\label{def:lmpgmp}
	Let $({\mathscr A},\mu)$ be a multiarrangement in $\mathbb{C}^\ell$. Let $0 \le k \le \ell$. 
	\begin{itemize}
		\item[(i)] If the localization $({\mathscr A}_X,\mu_X)$ is free with exponents $\exp({\mathscr A}_X,\mu_X)=(e_1^X,e_2^X,\dots, e_k^X)$ for each $X\in L({\mathscr A})_k$, then define the \emph{$k$-th local mixed product} by
		\[\operatorname{LMP} (k)=\sum_{X\in L_k} e_1^X e_2^X\cdots e_k^X.\] 
		\item[(ii)] If $({\mathscr A},\mu)$ is free with exponents $\exp({\mathscr A},\mu)=(e_1,\dots,e_\ell)$, define the \emph{$k$-th global mixed product} by \[\operatorname{GMP} (k)=\sum e_{i_1}e_{i_2}\cdots e_{i_k},\] where the sum is taken over all $k$-tuples from $\exp({\mathscr A},\mu)$ with $1\leq i_1<\dots<i_k\leq \ell$.
	\end{itemize}

\label{MixedEquality}
	If $({\mathscr A},\mu)$ is free with $\exp({\mathscr A},\mu)=(e_1,\dots, e_\ell)$ then for every $0\leq k\leq \ell$, we have 
	\[\operatorname{GMP} (k)=\operatorname{LMP} (k).\]

\label{rem:GMP_LMP_balanced}
Following \cite{abeteraowakefield:multichapol}, given two ordered $\ell$-tuples of non-negative integers, $(d_1,d_2,\dots,d_\ell)_\le$ and $(e_1,e_2,\dots,e_\ell)_\le$ as above satisfying $\sum d_i=\sum e_i$, we call $(d_1,d_2,\dots,d_\ell)_\le$ \emph{more balanced} than $(e_1,e_2,\dots,e_\ell)_\le$ if $d_\ell-d_1<e_\ell-e_1$. 
It follows from \cite[p.836]{abeteraowakefield:multichapol}
that if $(d_1,d_2,\dots,d_\ell)_\le$ is more balanced than $(e_1,e_2,\dots,e_\ell)_\le$, then $\operatorname{GMP} (k)$ is larger for $(d_1,d_2,\dots,d_\ell)_\le$ than for $(e_1,e_2,\dots,e_\ell)_\le$.

\label{lemma:LMP_GMP_nonfree}
 Let ${\mathscr A}$ be a simple arrangement in $\mathbb{K}^\ell$. 
\begin{itemize}
    \item [(i)]  Let $\mu$ be a multiplicity on ${\mathscr A}$ and let $(e_1,e_2,\dots,e_\ell)_\leq$ be the unique most balanced ordered $\ell$-tuple 
	of integers with sum equal to $\vert\mu\vert$. If the $\operatorname{GMP}(2)$ for $(e_1,\ldots,e_\ell)_\leq$ is smaller than the $\operatorname{LMP} (2)$ for $({\mathscr A},\mu)$, then $({\mathscr A},\mu)$ is not free.
    \item [(ii)]  Let
	$(e_2,\dots,e_\ell)_\leq$ be the unique most balanced ordered $\ell$-tuple
	of integers with sum equal to $\vert{\mathscr A}\vert-1$. If the $\operatorname{GMP}(2)$ for $(1,e_2,\ldots,e_\ell)_\leq$ is smaller than the $\operatorname{LMP} (2)$ for ${\mathscr A}$, then ${\mathscr A}$ is not free.
\end{itemize}

For each $G$ as in the statement above, we present an element $X\in L({\mathscr A}_G)$ in Table \ref{table: G3 to G20 totally non-free}  
	such that the corresponding localization $({\mathscr A}_G)_X$ is a generic arrangement with $\operatorname{rank} ({\mathscr A}_G)_X<\vert({\mathscr A}_G)_X\vert$. 
	Consequently, owing to Theorems \ref{theorem: Multilocalizations are free} and \ref{theorem: Yoshinaga generic not free} we conclude that ${\mathscr A}_G$ is totally non-free.

\label{theorem: free connected subgrapharrangement rank bigger 4}
	Let $G$ be a connected graph on at least $5$ vertices. Then there exists a multiplicity $\mu \ge \mathbbm{1}$ such that the connected subgraph multiarrangement $({\mathscr A}_G,\mu)$ is free if and only if $G$ is a path-graph, a cycle-graph, an almost-path-graph, or a path-with-triangle-graph.
		In particular, all other connected graphs with at least $5$ vertices yield totally non-free connected subgraph arrangements.

\label{proposition: Free G1 and G2 multiplicities}
	Let ${\mathscr A}\in\{{\mathscr A}_{G_1},{\mathscr A}_{G_2}\}$. There exists a multiplicity $\mu \ne \mathbbm{1}$ such that $({\mathscr A},\mu)$ is free.
	In particular, there exists a multiplicity $\mu$ such that $({\mathscr A}_{G_2},\mu)$ is recursively free but not additively free.

\label{rem:alg1}
	\textbf{Algorithm to calculate $\operatorname{LMP} (2)$ for a simple ${\mathscr A}_G$:}
	\begin{enumerate}
		\item  Determine the number of all types (i.e.~path-graph, almost-path-graph, etc.) of connected
		induced subgraphs $G[S]$ of $G = (N, E)$, where $S \subseteq N$ and $\vert S\vert \geq 2$. 

		\item For every subgraph $G[S]$ from step $(1)$ we determine the number of triples of the form  $(G[S],G[I],G[J])$,
		where $G[I],G[J]$ are connected induced subgraphs of $G[S]$ with $I \, \dot{\cup} \, J = S$. Adding up the number of all such triples for all connected induced subgraphs $G'$ from (1) provides  an invariant $\nu_1$. Using Lemma \ref{lemma: connected subgraph arrangements are locallyA2} we see that for a fixed graph $G'$ this is just the number of rank $2$ localizations with $N(G')=A_{i_3}$, with the notation as in the lemma. 

		\item Calculate $\nu_2:=\binom{\vert{\mathscr A}_G\vert}{2}$. If all rank $2$ localizations were to consist of exactly two elements, then $\nu_2$ would be the number of all rank $2$ localizations.

		\item We have $\operatorname{LMP} (2)= \nu_2-\nu_1$. To see this, a rank $2$ localization with two elements is free with exponents $(1,1)$, while a rank $2$ localization with three elements is free with exponents $(1,2)$. So if instead of having three rank $2$ localizations with two elements we have one rank $2$ localization with three elements, then $\operatorname{LMP} (2)$ gets decreased by $1$ (since we assume for $\nu_2$ that all localizations contain exactly two elements). Since $\nu_1$ is the number of rank $2$ localizations with three elements, $\nu_2-\nu_1$ coincides with $\operatorname{LMP} (2)$.
	\end{enumerate}

\label{rem:alg2}
	\textbf{Algorithm to calculate $\operatorname{LMP} (2)$ for a constant multiplicity $\mu\equiv c$:}
	\begin{enumerate}
		\item Determine the number of all types of connected induced subgraphs of $G$ with at least $2$ vertices (i.e.~path-graph, almost-path-graph, etc.). 
		\item For every subgraph $G'$ from step (1) we determine the number of triples $(G',G[I],G[J])$, where $G[I],G[J]$ are connected induced subgraphs of $G'$ with $N(G[I])\cup N(G[J])=N(G')$. Let $\nu_1$ be the sum of the number of all such triples for all connected induced subgraphs $G'$ from part (1).
		\item Calculate $\nu_2:=\binom{\vert{\mathscr A}_G\vert}{2}$. 
		\item Since $\nu_1$ is the number of rank $2$ localizations with three elements, the number of rank $2$ localizations with two elements is equal to $\nu_3:=\nu_2-3 \nu_1$, because if there is one rank $2$ localization with three elements, then the hyperplanes of this localization could have potentially formed three rank $2$ localizations with two elements. 
		\item Using Theorem \ref{WakaTheo} we derive the exponents of all rank $2$ localizations with three elements (which depends on the parity of $c$), while localizations of rank $2$ with two elements are free with exponents $(c,c)$. We get $$
		\operatorname{LMP} (2)=\begin{cases}
			\nu_1\cdot\left(\frac{3c}{2}\right)^2+\nu_3  c^2, & \text{ (if }c\text{ is even),}\\
			\nu_1\cdot\left(\frac{3c-1}{2}\cdot \frac{3c+1}{2}\right)+\nu_3  c^2, & \text{ (if }c\text{ is odd).}
		\end{cases}
		$$
	\end{enumerate}

We define the \emph{deleted $C_3$ arrangement} $\mathscr{D}$ as $\mathscr{D}:={\mathscr A}_{C_3}\backslash\{H_{123}\}$. The defining polynomial of $\mathscr{D}$ is given by 
	\begin{equation}
		\label{eq:D}
		Q(\mathscr{D})=x_1x_2x_3(x_1+x_2)(x_1+x_3)(x_2+x_3).
	\end{equation}

\label{lemma: special B2 multiplicities}
	Let $({\mathscr A},\mu)=({\mathscr A}(B_2),\mu)$ be the multiarrangement $$Q({\mathscr A}(B_2),\mu)=x_1^ax_2^b(x_1+x_2)^c(2x_1+x_2)^d$$ with multiplicity $\mu=(a,b,c,d)$.
	\begin{enumerate}
		\item If $\mu=(2k,1,2k,1)$, then $({\mathscr A},\mu)$ is free with exponents $(2k+1,2k+1)$.
		\item If $\mu=(2k+1,1,2k+1,1)$, then $({\mathscr A},\mu)$ is free with exponents $(2k+1,2k+3)$.
		\item If $\mu=(k,1,k,2k-4)$ or $\mu=(k,2k-4,k,1)$, then $({\mathscr A},\mu)$ is free with exponents $(2k-2,2k-1)$.
		\item If $\mu=(k+1,1,k+1,2k-4)$ or $\mu=(k+1,2k-4,k+1,1)$, then $({\mathscr A},\mu)$ is free with exponents $(2k-1,2k)$.
	\end{enumerate}

\label{lemma: 3evenMustBeEqual}
	Let $Q(\mathscr{D},\mu)=x_1^ax_2^bx_3^c(x_1+x_2)^d(x_1+x_3)^e(x_2+x_3)^f$ with multiplicity $\mu=(a,b,c,d,e,f), a\geq b\geq c$. If $\mu=(even,even,even,1,1,1)$, then
		$(\mathscr{D},\mu)$ is free if and only if $a=b=c$.

\label{lemma: localFreenessWithoutStar}
	Let $Q({\mathscr A},\mu)=x_1^{m_1}x_2^{m_2}(x_1+x_2)^{m_3}$ with $m_1\leq m_2$. Let $\sigma=(0,0,1)$.
	\begin{itemize}
		\item[(i)] If $\mu = (m_1,m_2,m_3)=(even,even,odd)$, then ${\mathscr E}_\sigma({\mathscr A},\mu)$ is free.
		\item[(ii)] If $\mu =  (m_1,m_2,m_3)=(even,odd,odd)$ or $(odd,even,odd)$, then ${\mathscr E}_\sigma({\mathscr A},\mu)$ is free.
	\end{itemize}

\label{Theorem: AllDMultiplicities}
	Let $(\mathscr{D},\mu)$ be the multiarrangement $$Q(\mathscr{D},\mu)=x_1^ax_2^bx_3^c(x_1+x_2)^d(x_1+x_3)^e(x_2+x_3)^f$$ with $a,b,c,d,e,f \geq 1$. Then
	$(\mathscr{D},\mu)$ is free if and only if  $\mu=(2k,2k,2k,1,1,1)$ for some $k\in\mathbb{N}_{\geq 1}$ where the order of the hyperplanes is as above.

\label{def:ss}
    An arrangement ${\mathscr A}$ is supersolvable if there exists a filtration
${\mathscr A} = {\mathscr A}_r \supset {\mathscr A}_{r-1}\supset\dots\supset {\mathscr A}_2 \supset {\mathscr A}_1$
such that:
\begin{itemize}
    \item $\operatorname{rank}({\mathscr A}_i ) = i$ for  $i = 1, \dots , r$;
    \item for any $H, H'\in {\mathscr A}_i$, there exists some $H''\in {\mathscr A}_{i-1}$ such that $H\cap H'\subset H''$.
\end{itemize}

\label{prop:SpecialFreeMultC_3}
	Let $({\mathscr A}_{C_3},\mu)$ be the multiarrangement $$Q({\mathscr A}_{C_3},\mu)=x_1^ax_2^bx_3^c(x_1+x_2)^d(x_1+x_3)^e(x_2+x_3)^f(x_1+x_2+x_3)^g$$ with multiplicity $\mu=(a,b,c,d,e,f,g), (d\geq e\geq f)$. Suppose that
	\begin{enumerate}
		\item[(i)] $\mu=(k,k,k,r,1,1,k)$, where $1\leq k \leq 3$ arbitrary and $r\geq 1$, or
		\item[(ii)] $\mu=(k,k,k,r,1,1,k)$, where $k>3$ arbitrary and $r\geq                
  2k-5$.
	\end{enumerate}
	Then $({\mathscr A}_{C_3},\mu)$ is free. Moreover, if $r\geq 2k$, then $({\mathscr A}_{C_3},\mu)$ is  inductively free with exponents $(r,2k+1,2k+1)$.
    For $\mu = (3,3,3,1,1,1,3)$, $({\mathscr A}_{C_3},\mu)$ is not inductively free.
